style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://i.imgur.com/PLACEHOLDER.jpg");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(120, 90, 160, 0.22);
    pointer-events: none;
  }

  * {
    text-shadow: 0 0 6px rgba(160, 120, 255, 0.25);
  }
}

@-moz-document domain("roblox.com") {
body, * {
    font-family: "Adelina", sans-serif !important;
  }
}
